CREATE SCHEMA maintenance;
CREATE TABLE maintenance.warranties (id uuid PRIMARY KEY, tenant_id text NOT NULL, asset_id uuid NOT NULL, provider text NOT NULL, contract_ref text, starts_at date NOT NULL, ends_at date NOT NULL, coverage text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CHECK (ends_at >= starts_at));
CREATE TABLE maintenance.orders (id uuid PRIMARY KEY, tenant_id text NOT NULL, asset_id uuid NOT NULL, title text NOT NULL, description text NOT NULL, state text NOT NULL DEFAULT 'DRAFT', version integer NOT NULL DEFAULT 1, warranty_id uuid REFERENCES maintenance.warranties(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK (state IN ('DRAFT','OPEN','DIAGNOSING','WAITING_APPROVAL','WAITING_PART','WAITING_VENDOR','IN_REPAIR','VERIFYING','COMPLETED','CANCELLED','FAILED')));
CREATE INDEX maintenance_orders_lookup ON maintenance.orders(tenant_id,state,created_at DESC); CREATE INDEX warranties_asset_dates ON maintenance.warranties(tenant_id,asset_id,starts_at,ends_at);
